def astype(self, dtype, copy=True):
    dtype = pandas_dtype(dtype)
    if isinstance(dtype, StringDtype):
        if copy:
            return self.copy()
        return self
    elif isinstance(dtype, Int64Dtype):
        values = self.astype(object).to_numpy()
        mask = pd.isna(values)
        values[~mask] = values[~mask].astype(int)
        result = pd.array(values, dtype='Int64')
        return result
    return super().astype(dtype, copy)
```

